import type { BehaviorRow } from "./types.test";

export default [
  { tool: "Bash", input: "cd ~/Library && du -sh", cwd: "$H", claude: 2, codex: 2 },
  { tool: "Bash", input: "cd --; rg needle", cwd: "$H/project", claude: 2, codex: 2, reason: "broad" },
  { tool: "Bash", input: "rg needle", cwd: "$H/project/data-link/..", claude: 2, codex: 2, reason: "broad" },
  { tool: "Bash", input: "cd data-link/.. && rg needle", cwd: "$H/project", claude: 0, codex: 0, note: "logical cd returns to the project before rg runs" },
  { tool: "Grep", input: "", cwd: "$H/project/data-link/..", claude: 2, reason: "appdata" },
  { tool: "Bash", input: "cd ~/Library && rg foo", cwd: "$H", claude: 2, codex: 2 },
  { tool: "Bash", input: "cd /tmp & ls -R", cwd: "$H/Library", claude: 2, codex: 2, note: "a background cd does not move this shell" },
  { tool: "Bash", input: "cd /nope || ls -R", cwd: "$H/Library", claude: 2, codex: 2, note: "the right side of || runs only when cd failed" },
  { tool: "Bash", input: "cd project |& ls -R", cwd: "$H", claude: 2, codex: 2, note: "a cd inside a pipeline does not move the next element" },
  { tool: "Bash", input: "cd ~/Library || exit 1; ls -R", cwd: "$H", claude: 2, codex: 2 },
  { tool: "Bash", input: "cd ~/Library || true; ls -R", cwd: "$H", claude: 2, codex: 2 },
  { tool: "Bash", input: "cd ~/Library; f() { cd /tmp; }; ls -R", cwd: "$H", claude: 2, codex: 2 },
  { tool: "Bash", input: "cd ~/Library; cd /tmp; cd -; ls -R", cwd: "$H", claude: 2, codex: 2 },
  { tool: "Bash", input: "cd ~/Library && cd /tmp && cd - && rg needle", cwd: "$H/project", claude: 2, codex: 2, reason: "broad" },
  { tool: "Bash", input: "cd /nope || true; ls -R", cwd: "$H/Library", claude: 2, codex: 2 },
  { tool: "Bash", input: 'D=/tmp; ls "${D:+~/Library/Containers/x}"', cwd: "$H", claude: 2, codex: 2 },
  { tool: "Bash", input: "cd ~/Library; if false; then cd /tmp; fi; ls -R", cwd: "$H", claude: 2, codex: 2 },
  { tool: "Bash", input: "cd ~/Library; if true; then cd /tmp; else ls -R; fi", cwd: "$H", claude: 2, codex: 2 },
  { tool: "Bash", input: "cd /definitely-no-such-dir; ls -R", cwd: "$H/Library", claude: 2, codex: 2 },
  { tool: "Bash", input: "cd ~/Library; while false; do cd /tmp; done; ls -R", cwd: "$H", claude: 2, codex: 2 },
  { tool: "Bash", input: "cd ~/project && du -sh", cwd: "$H", claude: 0, codex: 0 },
  { tool: "Bash", input: "cd $H/Library/Containers/com.x && echo ready", cwd: "$H/project", claude: 0, codex: 0, note: "entering a protected directory and printing a literal does not read it" },
  { tool: "Bash", input: "cd Code && rg --no-ignore foo", cwd: "$H", claude: 0, codex: 0 },
  { tool: "Bash", input: "cd ~/project && npm test && du -sh", cwd: "$H", claude: 0, codex: 0 },
  { tool: "Bash", input: "pushd ~/project && du -sh", cwd: "$H", claude: 0, codex: 0 },
  { tool: "Bash", input: "cd ~/project; du -sh", cwd: "$H", claude: 2, codex: 2, note: "A semicolon does not prove cd succeeded; the old broad cwd remains possible." },
  {
    tool: "Bash",
    input: "cd a; cd b; cd c; cd d; cd e; cd f; cd g; cd h; cd i; cd j; cd k; cd l; cd m; cd n; cd o; cd p; cd q; cd r; cd s; cd t; cd u; cd v; cat Library/Containers/x",
    cwd: "$H",
    claude: 2,
    codex: 2,
  },
  { tool: "Bash", input: "pushd ~/project && popd && du -sh", cwd: "$H", claude: 2, codex: 2 },
  { tool: "Bash", input: "pushd ~/project && pushd && du -sh", cwd: "$H", claude: 2, codex: 2 },
  { tool: "Bash", input: 'cd ~/project && cd "$OLDPWD" && du -sh', cwd: "$H", claude: 2, codex: 2 },
  {
    tool: "Bash",
    input: "f() { cd ~/Library; }; f; cat Containers/x",
    cwd: "$H",
    claude: 2,
    codex: 2,
    reason: "appdata",
    note: "a function call runs its body in the caller's shell, so its cd moves the caller",
  },
  { tool: "Bash", input: "f() { find .; }; cd ~; f", cwd: "$H/project", claude: 2, codex: 2, reason: "broad", note: "the body runs in the directory the caller has when it calls" },
  { tool: "Bash", input: "function f { ls -R .; }; cd ~; f", cwd: "$H/project", claude: 2, codex: 2, reason: "broad" },
  { tool: "Bash", input: "f() { ls; }; f", cwd: "$H/project", claude: 0, codex: 0 },
  { tool: "Bash", input: "f() { cd /usr; }; f; ls -R", cwd: "$H/project", claude: 0, codex: 0 },
  { tool: "Bash", input: "true | cd ~/Library; cat Containers/x", cwd: "$H", claude: 2, codex: 2, reason: "appdata", note: "zsh runs the last element of a pipeline in the current shell" },
  { tool: "Bash", input: "true | cd ~; find .", cwd: "$H/project", claude: 2, codex: 2, reason: "broad" },
  { tool: "Bash", input: "cd ~/Library && cat $PWD/Containers/x", cwd: "$H", claude: 2, codex: 2, reason: "appdata" },
  { tool: "Bash", input: 'cd ~/Library && cat "${PWD}/Containers/x"', cwd: "$H", claude: 2, codex: 2, reason: "appdata" },
  { tool: "Bash", input: "cd ~/Library && cat $(pwd)/Containers/x", cwd: "$H", claude: 2, codex: 2, reason: "appdata" },
  { tool: "Bash", input: "cd ~/Library && cat `pwd`/Containers/x", cwd: "$H", claude: 2, codex: 2, reason: "appdata" },
  { tool: "Bash", input: "cd ~/Library && ls ~+/Containers", cwd: "$H", claude: 2, codex: 2, reason: "appdata", note: "~+ is $PWD" },
  { tool: "Bash", input: "cd /nope; cat $PWD/Containers/x", cwd: "$H/Library", claude: 2, codex: 2, reason: "appdata", note: "when cd fails, $PWD is still the old directory" },
  { tool: "Bash", input: "cat $PWD/file.txt", cwd: "$H/project", claude: 0, codex: 0 },
  { tool: "Bash", input: "cd -P && find .", cwd: "$H/project", claude: 2, codex: 2, reason: "broad", note: "cd with only -P, -L, -q or -s goes home" },
  { tool: "Bash", input: "cd -L && find .", cwd: "$H/project", claude: 2, codex: 2, reason: "broad" },
  { tool: "Bash", input: "cd -e && find .", cwd: "$H/project", claude: 0, codex: 0, note: "neither bash nor zsh takes -e alone, so cd fails and find does not run" },
  { tool: "Bash", input: "cd -q && find .", cwd: "$H/project", claude: 2, codex: 2, reason: "broad", note: "zsh cd -q and cd -s with no directory go home" },
  { tool: "Bash", input: "cd -s && find .", cwd: "$H/project", claude: 2, codex: 2, reason: "broad" },
  { tool: "Bash", input: "cd -P nested && find .", cwd: "$H/project", claude: 0, codex: 0 },
  { tool: "Bash", input: "cd -P data-link/.. && cat Containers/x", cwd: "$H/project", claude: 2, codex: 2, reason: "appdata", note: "a physical cd resolves the link before `..`" },
  { tool: "Bash", input: "cd -L data-link/.. && cat Containers/x", cwd: "$H/project", claude: 0, codex: 0, note: "a logical cd cancels the link lexically" },
  { tool: "Bash", input: "cd -L -P data-link/.. && cat Containers/x", cwd: "$H/project", claude: 2, codex: 2, reason: "appdata", note: "bash and zsh both obey a final -P" },
  { tool: "Bash", input: "cd -P -L data-link/.. && cat Containers/x", cwd: "$H/project", claude: 2, codex: 2, reason: "appdata", note: "zsh obeys -P anywhere; bash obeys the final -L" },
  { tool: "Bash", input: "cd -P cache-link/.. && cd -P -L escape-link/.. && cat keys/private.$UNSET_VARIABLE", cwd: "$H/project", claude: 2, codex: 2, reason: "file" },
  {
    tool: "Bash",
    input: "cd -P cache-link/.. && cd ../Containers && cat x",
    cwd: "$H/project",
    claude: 2,
    codex: 2,
    reason: "appdata",
    note: "later logical cds keep the physical directory",
  },
  { tool: "Bash", input: "cd -P data-link/.. && cd /tmp && cat x", cwd: "$H/project", claude: 0, codex: 0, note: "cat runs only after both cds succeed" },
  { tool: "Bash", input: "cd data-link && cd /tmp && cat x", cwd: "$H/project", claude: 0, codex: 0 },
  {
    tool: "Bash",
    input: "cd -P data-link/.. && cd /nope; cat Containers/x",
    cwd: "$H/project",
    claude: 2,
    codex: 2,
    reason: "appdata",
    note: "after the chain, a failed cd leaves the physical directory",
  },
  {
    tool: "Bash",
    input: "cd -P data-link/.. && { cd /nope; cat Containers/x; }",
    cwd: "$H/project",
    claude: 2,
    codex: 2,
    reason: "appdata",
    note: "inside the group, cat runs after a failed cd",
  },
  {
    tool: "Bash",
    input: "f() { cd /nope; cat ../Containers/x; }; cd -P cache-link/.. && f",
    cwd: "$H/project",
    claude: 2,
    codex: 2,
    reason: "appdata",
    note: "inside the function, cat runs after a failed cd",
  },
  {
    tool: "Bash",
    input: "cd -P data-link/.. && echo $(cd /nope; cat Containers/x)",
    cwd: "$H/project",
    claude: 2,
    codex: 2,
    reason: "appdata",
    note: "inside the substitution, cat runs after a failed cd",
  },
  { tool: "Bash", input: "cd -P data-link/.. && env -C . cat Containers/x", cwd: "$H/project", claude: 2, codex: 2, reason: "appdata", note: "env -C changes directory physically" },
  { tool: "Bash", input: "env -C data-link/.. cat Containers/x", cwd: "$H/project", claude: 2, codex: 2, reason: "appdata" },
  { tool: "Bash", input: "fd -C cache-link/.. . ../Containers", cwd: "$H/project", claude: 2, codex: 2, reason: "appdata" },
  { tool: "Bash", input: "fd --base-directory=cache-link/.. . ../Containers", cwd: "$H/project", claude: 2, codex: 2, reason: "appdata" },
  { tool: "Bash", input: "cd -P data-link/.. && fd -C . . Containers", cwd: "$H/project", claude: 2, codex: 2, reason: "appdata" },
  { tool: "Bash", input: "cd ../.. && cat Containers/x", cwd: "$H/project/data-link/./com.x", claude: 0, codex: 0, note: "a dot in the hook's directory is not a physical step" },
  {
    tool: "Bash",
    input: "cd data-link/com.*/ && echo ready",
    cwd: "$H/project",
    claude: 2,
    codex: 2,
    reason: "appdata",
    note: "the shell expands a directory glob through a protected alias before cd",
  },
] satisfies BehaviorRow[];
